<?php
declare(strict_types=1);namespace MiniErp\Platform;use MiniErp\Context\AuthenticatedPlatformAdmin;use MiniErp\Repositories\PlatformAdminRepository;use PDO;use RuntimeException;final class MultiTenantMigrationService{public function __construct(private PDO $main,private MigrationCatalog $catalog,private MultiTenantMigrationPrecheck $precheck,private MultiTenantOperationRepository $operations,private PlatformAdminRepository $audit,private MultiTenantMigrationExecutor $executor){}public function simulate(AuthenticatedPlatformAdmin $admin,string $migrationId,array $tenantIds):array{if(!in_array($admin->getRole(),['SUPER_ADMIN','GLOBAL_TECH'],true))throw new RuntimeException('Role não autorizada a executar migrations.');$migration=$this->catalog->get($migrationId);$ids=array_values(array_unique(array_filter(array_map('intval',$tenantIds),fn($id)=>$id>0)));if($ids===[])throw new RuntimeException('Selecione ao menos um tenant.');$results=[];foreach($this->tenants($ids,$admin) as $tenant)$results[]=$this->precheck->check($tenant,$migration);$plan=$this->operations->createPlan($admin->getUserId(),$migration,$ids,$results,600);$this->audit->audit($admin->getUserId(),'MULTITENANT_DRY_RUN','migration',$migrationId,null,['plan_id'=>$plan,'tenant_ids'=>$ids,'write_performed'=>false]);return['plan_id'=>$plan,'expires_in'=>600,'migration'=>$migration,'results'=>$results,'write_performed'=>false];}public function execute(AuthenticatedPlatformAdmin $admin,string $planId,string $confirmation,string $reason):array{if(!in_array($admin->getRole(),['SUPER_ADMIN','GLOBAL_TECH'],true))throw new RuntimeException('Role não autorizada.');$plan=$this->operations->consumePlan($planId,$admin->getUserId());$this->tenants($plan['tenant_ids'],$admin);$migration=$this->catalog->get($plan['migration_id']);if(!hash_equals($plan['checksum'],$migration['checksum'])||!hash_equals($migration['checksum'],hash_file('sha256',$migration['path'])))throw new RuntimeException('CHECKSUM_MISMATCH');$expected='EXECUTAR EM '.count($plan['tenant_ids']).' EMPRESAS';if(!hash_equals($expected,trim($confirmation)))throw new RuntimeException('ConfirmaÃ§Ã£o textual invÃ¡lida.');if(trim($reason)==='')throw new RuntimeException('Motivo obrigatÃ³rio.');$operation=$this->operations->createOperation($plan,$migration,$reason);$this->audit->audit($admin->getUserId(),'MULTITENANT_EXECUTION_REQUESTED','operation',$operation,null,['plan_id'=>$planId,'migration_id'=>$migration['migration_id']]);$results=[];foreach($this->tenants($plan['tenant_ids'],$admin) as $tenant){$check=$this->precheck->check($tenant,$migration);if($check['status']!=='READY'){$this->operations->addTarget($operation,(int)$tenant['tenant_id'],(string)$tenant['db_name'],$check['status']);$results[]=$check;continue;}$this->audit->audit($admin->getUserId(),'MULTITENANT_MIGRATION_STARTED','tenant',(string)$tenant['tenant_id'],null,['operation_id'=>$operation]);$result=$this->executor->execute($operation,$tenant,$migration);$results[]=$result+['tenant_id'=>(int)$tenant['tenant_id']];$action=$result['status']==='SUCCESS'?'MULTITENANT_MIGRATION_SUCCESS':'MULTITENANT_MIGRATION_FAILED';$this->audit->audit($admin->getUserId(),$action,'tenant',(string)$tenant['tenant_id'],null,['operation_id'=>$operation,'status'=>$result['status']]);}$success=count(array_filter($results,fn($r)=>$r['status']==='SUCCESS'));$final=$success===count($results)?'SUCCESS':($success>0?'PARTIAL':'FAILED');$this->operations->finish($operation,$final);$this->audit->audit($admin->getUserId(),$final==='PARTIAL'?'MULTITENANT_OPERATION_PARTIAL':'MULTITENANT_OPERATION_COMPLETED','operation',$operation,null,['status'=>$final]);return['operation_id'=>$operation,'status'=>$final,'results'=>$results];}private function tenants(array $ids,AuthenticatedPlatformAdmin $admin):array{$marks=implode(',',array_fill(0,count($ids),'?'));$s=$this->main->prepare("SELECT id AS tenant_id,nome_fantasia,db_name,status,blocked FROM tenants WHERE id IN ($marks) ORDER BY id");$s->execute($ids);$rows=$s->fetchAll(PDO::FETCH_ASSOC);if(count($rows)!==count($ids))throw new RuntimeException('Tenant fora do plano ou inexistente.');foreach($rows as $tenant)\MiniErp\Authorization\PlatformDatabaseAccess::assertCanView($admin,$tenant);return$rows;}}
